1	package anthropic
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"net/http"
9		"os"
10		"strings"
11	
12		"forge/internal/domain"
13		"forge/internal/provider"
14	)
15	
16	// Client implements provider.Provider for the Anthropic Messages API.
17	type Client struct {
18		apiKey     string
19		baseURL    string
20		httpClient *http.Client
21		model      string
22		useBearer  bool     // use Authorization: Bearer instead of x-api-key
23		betaFlags  []string // anthropic-beta header values
24	}
25	
26	// New returns a Client. If apiKey is empty, ANTHROPIC_API_KEY env is used.
27	// model is the default model when Request.Model is empty.
28	func New(apiKey, model string) *Client {
29		if apiKey == "" {
30			apiKey = os.Getenv("ANTHROPIC_API_KEY")
31		}
32		return &Client{
33			apiKey:     apiKey,
34			baseURL:    "https://api.anthropic.com",
35			httpClient: &http.Client{},
36			model:      model,
37		}
38	}
39	
40	// NewBearer returns a Client that authenticates with Authorization: Bearer
41	// instead of x-api-key. Used for OAuth tokens (e.g. Claude Code credentials).
42	// Includes the oauth-2025-04-20 beta flag required for OAuth acceptance.
43	func NewBearer(token, model string) *Client {
44		return &Client{
45			apiKey:     token,
46			baseURL:    "https://api.anthropic.com",
47			httpClient: &http.Client{},
48			model:      model,
49			useBearer:  true,
50			betaFlags:  []string{"oauth-2025-04-20"},
51		}
52	}
53	
54	// Stream implements provider.Provider.
55	func (c *Client) Capabilities() provider.Capabilities {
56		return provider.Capabilities{provider.CapForgeLoop, provider.CapSystemPrompt}
57	}
58	
59	func (c *Client) Stream(ctx context.Context, req provider.Request) (<-chan provider.Delta, error) {
60		model := req.Model
61		if model == "" {
62			model = c.model
63		}
64	
65		body, err := c.buildBody(req, model)
66		if err != nil {
67			return nil, fmt.Errorf("anthropic: build request: %w", err)
68		}
69	
70		httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/v1/messages", bytes.NewReader(body))
71		if err != nil {
72			return nil, fmt.Errorf("anthropic: new request: %w", err)
73		}
74		httpReq.Header.Set("content-type", "application/json")
75		if c.useBearer {
76			httpReq.Header.Set("authorization", "Bearer "+c.apiKey)
77		} else {
78			httpReq.Header.Set("x-api-key", c.apiKey)
79		}
80		httpReq.Header.Set("anthropic-version", "2023-06-01")
81		if len(c.betaFlags) > 0 {
82			httpReq.Header.Set("anthropic-beta", strings.Join(c.betaFlags, ","))
83		}
84	
85		ch := make(chan provider.Delta, 32)
86		go c.stream(ctx, httpReq, model, ch)
87		return ch, nil
88	}
89	
90	// buildBody marshals the provider.Request into the Anthropic API request JSON.
91	func (c *Client) buildBody(req provider.Request, model string) ([]byte, error) {
92		maxTokens := req.MaxTokens
93		if maxTokens == 0 {
94			maxTokens = 8192
95		}
96	
97		msgs := make([]apiMessage, len(req.Messages))
98		for i, m := range req.Messages {
99			msgs[i] = convertMessage(m)
100		}
101	
102		var tools []apiTool
103		if len(req.Tools) > 0 {
104			tools = make([]apiTool, len(req.Tools))
105			for i, t := range req.Tools {
106				tools[i] = apiTool{
107					Name:        t.Name,
108					Description: t.Description,
109					InputSchema: t.InputSchema,
110				}
111			}
112		}
113	
114		body := apiRequest{
115			Model:     model,
116			MaxTokens: maxTokens,
117			System:    req.System,
118			Messages:  msgs,
119			Tools:     tools,
120			Stream:    true,
121		}
122		return json.Marshal(body)
123	}
124	
125	// stream runs the HTTP call and SSE processing in a goroutine.
126	func (c *Client) stream(ctx context.Context, httpReq *http.Request, model string, ch chan<- provider.Delta) {
127		defer close(ch)
128	
129		resp, err := c.httpClient.Do(httpReq)
130		if err != nil {
131			ch <- provider.Delta{Type: provider.DeltaTypeError, Err: fmt.Errorf("anthropic: %w", err)}
132			ch <- provider.Delta{Type: provider.DeltaTypeDone}
133			return
134		}
135		defer resp.Body.Close()
136	
137		if resp.StatusCode/100 != 2 {
138			var buf bytes.Buffer
139			_, _ = buf.ReadFrom(resp.Body)
140			ch <- provider.Delta{
141				Type: provider.DeltaTypeError,
142				Err:  fmt.Errorf("anthropic: %s: %s", resp.Status, strings.TrimSpace(buf.String())),
143			}
144			ch <- provider.Delta{Type: provider.DeltaTypeDone}
145			return
146		}
147	
148		sseEvents := make(chan sseEvent, 64)
149		go parseSSE(resp.Body, sseEvents)
150	
151		type blockState struct {
152			kind  string // "text" | "tool_use"
153			id    string
154			name  string
155			input strings.Builder
156		}
157	
158		blocks := map[int]*blockState{}
159		var inputTokens, outputTokens int64
160		var usageSent bool
161	
162		emitUsage := func() {
163			if !usageSent {
164				ch <- provider.Delta{
165					Type: provider.DeltaTypeUsage,
166					Usage: &domain.Usage{
167						InputTokens:  inputTokens,
168						OutputTokens: outputTokens,
169						CostUSD:      computeCost(model, inputTokens, outputTokens),
170					},
171				}
172				usageSent = true
173			}
174		}
175	
176		for {
177			select {
178			case <-ctx.Done():
179				ch <- provider.Delta{Type: provider.DeltaTypeError, Err: ctx.Err()}
180				ch <- provider.Delta{Type: provider.DeltaTypeDone}
181				return
182	
183			case ev, ok := <-sseEvents:
184				if !ok {
185					// SSE channel closed without message_stop.
186					emitUsage()
187					ch <- provider.Delta{Type: provider.DeltaTypeDone}
188					return
189				}
190	
191				switch ev.Type {
192				case "message_start":
193					var ms struct {
194						Message struct {
195							Usage struct {
196								InputTokens int64 `json:"input_tokens"`
197							} `json:"usage"`
198						} `json:"message"`
199					}
200					if json.Unmarshal([]byte(ev.Data), &ms) == nil {
201						inputTokens = ms.Message.Usage.InputTokens
202					}
203	
204				case "content_block_start":
205					var cbs struct {
206						Index        int `json:"index"`
207						ContentBlock struct {
208							Type string `json:"type"`
209							ID   string `json:"id"`
210							Name string `json:"name"`
211						} `json:"content_block"`
212					}
213					if json.Unmarshal([]byte(ev.Data), &cbs) == nil {
214						bs := &blockState{kind: cbs.ContentBlock.Type}
215						blocks[cbs.Index] = bs
216						if cbs.ContentBlock.Type == "tool_use" {
217							bs.id = cbs.ContentBlock.ID
218							bs.name = cbs.ContentBlock.Name
219							ch <- provider.Delta{
220								Type: provider.DeltaTypeToolUseStart,
221								ID:   bs.id,
222								Name: bs.name,
223							}
224						}
225					}
226	
227				case "content_block_delta":
228					var cbd struct {
229						Index int `json:"index"`
230						Delta struct {
231							Type        string `json:"type"`
232							Text        string `json:"text"`
233							PartialJSON string `json:"partial_json"`
234						} `json:"delta"`
235					}
236					if json.Unmarshal([]byte(ev.Data), &cbd) == nil {
237						bs := blocks[cbd.Index]
238						switch cbd.Delta.Type {
239						case "text_delta":
240							ch <- provider.Delta{
241								Type: provider.DeltaTypeText,
242								Text: cbd.Delta.Text,
243							}
244						case "input_json_delta":
245							if bs != nil {
246								bs.input.WriteString(cbd.Delta.PartialJSON)
247								ch <- provider.Delta{
248									Type:  provider.DeltaTypeToolUseDelta,
249									ID:    bs.id,
250									Input: cbd.Delta.PartialJSON,
251								}
252							}
253						}
254					}
255	
256				case "content_block_stop":
257					var cbs struct {
258						Index int `json:"index"`
259					}
260					if json.Unmarshal([]byte(ev.Data), &cbs) == nil {
261						if bs := blocks[cbs.Index]; bs != nil && bs.kind == "tool_use" {
262							ch <- provider.Delta{
263								Type:  provider.DeltaTypeToolUseEnd,
264								ID:    bs.id,
265								Input: bs.input.String(),
266							}
267						}
268					}
269	
270				case "message_delta":
271					var md struct {
272						Usage struct {
273							OutputTokens int64 `json:"output_tokens"`
274						} `json:"usage"`
275					}
276					if json.Unmarshal([]byte(ev.Data), &md) == nil {
277						outputTokens = md.Usage.OutputTokens
278						emitUsage()
279					}
280	
281				case "message_stop":
282					emitUsage()
283					ch <- provider.Delta{Type: provider.DeltaTypeDone}
284					return
285				}
286			}
287		}
288	}
289	
290	// convertMessage converts a provider.Message to the Anthropic API message format.
291	func convertMessage(m provider.Message) apiMessage {
292		blocks := make([]apiBlock, len(m.Content))
293		for i, b := range m.Content {
294			blocks[i] = convertBlock(b)
295		}
296		return apiMessage{Role: string(m.Role), Content: blocks}
297	}
298	
299	// convertBlock converts a provider.ContentBlock to the Anthropic API block format.
300	func convertBlock(b provider.ContentBlock) apiBlock {
301		switch b.Type {
302		case "text":
303			return apiBlock{Type: "text", Text: b.Text}
304		case "tool_use":
305			input := b.Input
306			if len(input) == 0 {
307				input = json.RawMessage(`{}`)
308			}
309			return apiBlock{Type: "tool_use", ID: b.ID, Name: b.Name, Input: input}
310		case "tool_result":
311			return apiBlock{Type: "tool_result", ToolUseID: b.ID, Content: b.Content, IsError: b.IsError}
312		default:
313			return apiBlock{Type: b.Type, Text: b.Text}
314		}
315	}
316	
317	// --- Anthropic API wire types ---
318	
319	type apiRequest struct {
320		Model     string       `json:"model"`
321		MaxTokens int          `json:"max_tokens"`
322		System    string       `json:"system,omitempty"`
323		Messages  []apiMessage `json:"messages"`
324		Tools     []apiTool    `json:"tools,omitempty"`
325		Stream    bool         `json:"stream"`
326	}
327	
328	type apiMessage struct {
329		Role    string     `json:"role"`
330		Content []apiBlock `json:"content"`
331	}
332	
333	type apiBlock struct {
334		Type string `json:"type"`
335		// text
336		Text string `json:"text,omitempty"`
337		// tool_use
338		ID    string          `json:"id,omitempty"`
339		Name  string          `json:"name,omitempty"`
340		Input json.RawMessage `json:"input,omitempty"`
341		// tool_result
342		ToolUseID string `json:"tool_use_id,omitempty"`
343		Content   string `json:"content,omitempty"`
344		IsError   bool   `json:"is_error,omitempty"`
345	}
346	
347	type apiTool struct {
348		Name        string          `json:"name"`
349		Description string          `json:"description"`
350		InputSchema json.RawMessage `json:"input_schema"`
351	}
352	
