1	package anthropic
2	
3	import (
4		"bufio"
5		"io"
6		"strings"
7	)
8	
9	// sseEvent holds one parsed SSE event.
10	type sseEvent struct {
11		Type string
12		Data string
13	}
14	
15	// parseSSE reads SSE events from r until EOF or error.
16	// Sends each complete event (with non-empty Data) to events.
17	// Closes events when done.
18	func parseSSE(r io.Reader, events chan<- sseEvent) {
19		defer close(events)
20	
21		scanner := bufio.NewScanner(r)
22		var curType, curData string
23	
24		for scanner.Scan() {
25			line := scanner.Text()
26			switch {
27			case strings.HasPrefix(line, "event:"):
28				curType = strings.TrimSpace(line[6:])
29			case strings.HasPrefix(line, "data:"):
30				data := strings.TrimSpace(line[5:])
31				if data == "[DONE]" {
32					continue
33				}
34				curData = data
35			case line == "":
36				if curData != "" {
37					events <- sseEvent{Type: curType, Data: curData}
38				}
39				curType = ""
40				curData = ""
41			}
42		}
43	
44		// Send any trailing event not followed by a blank line.
45		if curData != "" {
46			events <- sseEvent{Type: curType, Data: curData}
47		}
48	}
