49	}
50	
51	func (c *Client) Stream(ctx context.Context, req provider.Request) (<-chan provider.Delta, error) {
52		model := req.Model
53		if model == "" {
54			model = c.model
55		}
56	
57		body, err := c.buildBody(req, model)
58		if err != nil {
59			return nil, fmt.Errorf("openai: build request: %w", err)
60		}
61	
62		httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/v1/chat/completions", bytes.NewReader(body))
63		if err != nil {
