76	func (c *Client) buildBody(req provider.Request, model string) ([]byte, error) {
77		maxTokens := req.MaxTokens
78		if maxTokens == 0 {
79			maxTokens = 8192
80		}
81	
82		var tools []apiTool
83		if len(req.Tools) > 0 {
84			tools = make([]apiTool, len(req.Tools))
85			for i, t := range req.Tools {
86				tools[i] = apiTool{
87					Type: "function",
88					Function: apiFuncDef{
89						Name:        t.Name,
90						Description: t.Description,
91						Parameters:  t.InputSchema,
92					},
93				}
94			}
95		}
96	
97		return json.Marshal(apiRequest{
98			Model:         model,
99			Messages:      buildMessages(req),
100			Tools:         tools,
101			Stream:        true,
102			StreamOptions: &apiStreamOptions{IncludeUsage: true},
103			MaxTokens:     maxTokens,
104		})
105	}
106	
107	// stream runs the HTTP call and SSE processing in a goroutine.
108	func (c *Client) stream(ctx context.Context, httpReq *http.Request, model string, ch chan<- provider.Delta) {
109		defer close(ch)
110	
111		resp, err := c.httpClient.Do(httpReq)
112		if err != nil {
113			ch <- provider.Delta{Type: provider.DeltaTypeError, Err: fmt.Errorf("openai: %w", err)}
114			ch <- provider.Delta{Type: provider.DeltaTypeDone}
115			return
116		}
117		defer resp.Body.Close()
118	
119		if resp.StatusCode/100 != 2 {
120			var buf bytes.Buffer
121			_, _ = buf.ReadFrom(resp.Body)
122			ch <- provider.Delta{
123				Type: provider.DeltaTypeError,
124				Err:  fmt.Errorf("openai: %s: %s", resp.Status, strings.TrimSpace(buf.String())),
125			}
126			ch <- provider.Delta{Type: provider.DeltaTypeDone}
127			return
128		}
129	
130		rawCh := make(chan string, 64)
131		go parseSSE(resp.Body, rawCh)
132	
133		type tcState struct {
134			id   string
135			name string
136			args strings.Builder
137		}
138		tcs := map[int]*tcState{}
139		var inputTokens, outputTokens int64
140		var usageSent bool
141	
142		emitUsage := func() {
143			if !usageSent {
144				ch <- provider.Delta{
145					Type: provider.DeltaTypeUsage,
146					Usage: &domain.Usage{
147						InputTokens:  inputTokens,
148						OutputTokens: outputTokens,
149						CostUSD:      computeCost(model, inputTokens, outputTokens),
150					},
151				}
152				usageSent = true
153			}
154		}
155	
156		for {
157			select {
158			case <-ctx.Done():
159				ch <- provider.Delta{Type: provider.DeltaTypeError, Err: ctx.Err()}
160				ch <- provider.Delta{Type: provider.DeltaTypeDone}
161				return
162	
163			case raw, ok := <-rawCh:
164				if !ok {
165					emitUsage()
166					ch <- provider.Delta{Type: provider.DeltaTypeDone}
167					return
168				}
169				if raw == "[DONE]" {
170					emitUsage()
171					ch <- provider.Delta{Type: provider.DeltaTypeDone}
172					return
173				}
174	
175				var ck chunk
176				if err := json.Unmarshal([]byte(raw), &ck); err != nil {
177					continue
178				}
179	
180				if ck.Usage != nil {
181					inputTokens = ck.Usage.PromptTokens
182					outputTokens = ck.Usage.CompletionTokens
183				}
184	
185				if len(ck.Choices) == 0 {
186					continue
187				}
188				choice := ck.Choices[0]
189	
190				if choice.Delta.Content != nil && *choice.Delta.Content != "" {
191					ch <- provider.Delta{Type: provider.DeltaTypeText, Text: *choice.Delta.Content}
192				}
193	
194				for _, tc := range choice.Delta.ToolCalls {
195					state := tcs[tc.Index]
196					if state == nil {
197						state = &tcState{}
198						tcs[tc.Index] = state
199					}
200					if tc.ID != "" {
201						state.id = tc.ID
202						state.name = tc.Function.Name
203						ch <- provider.Delta{
204							Type: provider.DeltaTypeToolUseStart,
205							ID:   state.id,
206							Name: state.name,
207						}
208					}
209					if tc.Function.Arguments != "" {
210						state.args.WriteString(tc.Function.Arguments)
211						ch <- provider.Delta{
212							Type:  provider.DeltaTypeToolUseDelta,
213							ID:    state.id,
214							Input: tc.Function.Arguments,
215						}
216					}
217				}
218	
219				if choice.FinishReason != nil {
220					fr := *choice.FinishReason
221					if fr == "tool_calls" || fr == "tool" {
222						indices := make([]int, 0, len(tcs))
223						for idx := range tcs {
224							indices = append(indices, idx)
225						}
226						slices.Sort(indices)
227						for _, idx := range indices {
228							state := tcs[idx]
229							ch <- provider.Delta{
230								Type:  provider.DeltaTypeToolUseEnd,
231								ID:    state.id,
232								Input: state.args.String(),
233							}
234						}
235					}
236				}
237			}
238		}
239	}
240	
241	// buildMessages converts a provider.Request to the OpenAI wire message format.
242	// One provider.Message may expand into multiple OpenAI messages.
243	func buildMessages(req provider.Request) []apiMessage {
244		var msgs []apiMessage
245	
246		if req.System != "" {
247			msgs = append(msgs, apiMessage{Role: "system", Content: req.System})
248		}
249	
250		for _, m := range req.Messages {
251			switch m.Role {
252			case domain.RoleUser:
253				// tool_result blocks become role="tool" messages first.
254				for _, b := range m.Content {
255					if b.Type == "tool_result" {
256						msgs = append(msgs, apiMessage{
257							Role:       "tool",
258							Content:    b.Content,
259							ToolCallID: b.ID,
260						})
261					}
262				}
263				// Text blocks concatenated into a user message.
264				var sb strings.Builder
265				for _, b := range m.Content {
266					if b.Type == "text" {
267						sb.WriteString(b.Text)
268					}
269				}
270				if sb.Len() > 0 {
271					msgs = append(msgs, apiMessage{Role: "user", Content: sb.String()})
272				}
273	
274			case domain.RoleAssistant:
275				var sb strings.Builder
276				var toolCalls []apiToolCall
277				for _, b := range m.Content {
278					switch b.Type {
279					case "text":
280						sb.WriteString(b.Text)
281					case "tool_use":
282						toolCalls = append(toolCalls, apiToolCall{
283							ID:   b.ID,
284							Type: "function",
285							Function: apiFunction{
286								Name:      b.Name,
287								Arguments: orEmptyObj(b.Input),
288							},
289						})
290					}
291				}
292				msg := apiMessage{Role: "assistant", ToolCalls: toolCalls}
293				if sb.Len() > 0 {
294					msg.Content = sb.String()
295				}
296				// nil Content marshals as JSON null — correct for tool-only assistant messages.
297				msgs = append(msgs, msg)
298			}
299		}
300	
301		return msgs
302	}
303	
304	// --- OpenAI API wire types ---
305	
306	type apiRequest struct {
307		Model         string            `json:"model"`
308		Messages      []apiMessage      `json:"messages"`
309		Tools         []apiTool         `json:"tools,omitempty"`
310		Stream        bool              `json:"stream"`
311		StreamOptions *apiStreamOptions `json:"stream_options,omitempty"`
312		MaxTokens     int               `json:"max_tokens,omitempty"`
313	}
314	
315	type apiStreamOptions struct {
316		IncludeUsage bool `json:"include_usage"`
317	}
318	
319	type apiMessage struct {
320		Role       string        `json:"role"`
321		Content    any           `json:"content"`
322		ToolCalls  []apiToolCall `json:"tool_calls,omitempty"`
323		ToolCallID string        `json:"tool_call_id,omitempty"`
324	}
325	
326	type apiToolCall struct {
327		ID       string      `json:"id"`
328		Type     string      `json:"type"`
329		Function apiFunction `json:"function"`
330	}
331	
332	type apiFunction struct {
333		Name      string `json:"name"`
334		Arguments string `json:"arguments"`
335	}
336	
337	type apiTool struct {
338		Type     string     `json:"type"`
339		Function apiFuncDef `json:"function"`
340	}
341	
342	type apiFuncDef struct {
343		Name        string          `json:"name"`
344		Description string          `json:"description"`
345		Parameters  json.RawMessage `json:"parameters"`
346	}
347	
348	// --- SSE chunk wire types ---
349	
350	type chunk struct {
351		Choices []chunkChoice `json:"choices"`
352		Usage   *chunkUsage   `json:"usage"`
353	}
354	
355	type chunkChoice struct {
356		Delta        chunkDelta `json:"delta"`
357		FinishReason *string    `json:"finish_reason"`
358	}
359	
360	type chunkDelta struct {
361		Content   *string    `json:"content"`
362		ToolCalls []tcChunk  `json:"tool_calls"`
363	}
364	
365	type tcChunk struct {
366		Index    int         `json:"index"`
367		ID       string      `json:"id"`
368		Function tcFuncChunk `json:"function"`
369	}
370	
371	type tcFuncChunk struct {
372		Name      string `json:"name"`
373		Arguments string `json:"arguments"`
374	}
375	
376	type chunkUsage struct {
377		PromptTokens     int64 `json:"prompt_tokens"`
378		CompletionTokens int64 `json:"completion_tokens"`
379	}
380	
381	// orEmptyObj returns the JSON string of input, defaulting to "{}" if empty.
382	func orEmptyObj(input json.RawMessage) string {
383		if len(input) == 0 {
384			return "{}"
385		}
386		return string(input)
387	}
388	
