1	package config
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	
10		"gopkg.in/yaml.v3"
11	)
12	
13	type Config struct {
14		Listen   string             `yaml:"listen"`
15		Backends map[string]Backend `yaml:"backends"`
16		Peers    []string           `yaml:"peers"`
17	}
18	
19	type Backend struct {
20		// Managed backend (llama-server)
21		Model     string   `yaml:"model"`      // HuggingFace ref, e.g. "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M"
22		Context   int      `yaml:"context"`    // Context window size
23		GPULayers int      `yaml:"gpu_layers"` // -ngl flag
24		Pooling   string   `yaml:"pooling"`    // "mean", "cls", "rank" — triggers --embedding flag
25		Extra     []string `yaml:"extra"`      // Additional llama-server flags
26	
27		// External backend (Ollama, OpenAI, Anthropic, etc.)
28		URL      string `yaml:"url"`      // If set, backend is external — no process management
29		APIKey   string `yaml:"api_key"`  // Bearer token or x-api-key
30		Provider string `yaml:"provider"` // "openai" (default) or "anthropic"
31	}
32	
33	// IsManaged reports whether wire manages the llama-server process for this backend.
34	func (b Backend) IsManaged() bool { return b.URL == "" }
35	
36	// IsExternal reports whether this backend is an external service.
37	func (b Backend) IsExternal() bool { return !b.IsManaged() }
38	
39	// ValidationError describes a config validation failure.
40	type ValidationError struct {
41		Field   string
42		Message string
43	}
44	
45	func (e *ValidationError) Error() string {
46		return fmt.Sprintf("config validation: %s: %s", e.Field, e.Message)
47	}
48	
49	// Load reads the config from disk, applies defaults, and validates it.
50	// Path resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
51	// ~/.config/wire/config.yaml.
52	func Load() (*Config, error) {
53		path := configPath()
54	
55		data, err := os.ReadFile(path)
56		if err != nil {
57			if errors.Is(err, os.ErrNotExist) {
58				return nil, fmt.Errorf("config file not found at %s: %w", path, err)
59			}
60			return nil, fmt.Errorf("reading config %s: %w", path, err)
61		}
62	
63		cfg := new(Config)
64		dec := yaml.NewDecoder(bytes.NewReader(data))
65		dec.KnownFields(true)
66		if err := dec.Decode(cfg); err != nil {
67			return nil, fmt.Errorf("parsing config %s: %w", path, err)
68		}
69	
70		applyDefaults(cfg)
71	
72		if err := validate(cfg); err != nil {
73			return nil, err
74		}
75	
76		return cfg, nil
77	}
78	
79	func configPath() string {
80		if v := os.Getenv("WIRE_CONFIG"); v != "" {
81			return v
82		}
83		base := os.Getenv("XDG_CONFIG_HOME")
84		if base == "" {
85			home, _ := os.UserHomeDir()
86			base = filepath.Join(home, ".config")
87		}
88		return filepath.Join(base, "wire", "config.yaml")
89	}
90	
91	func applyDefaults(cfg *Config) {
92		if cfg.Listen == "" {
93			cfg.Listen = ":8080"
94		}
95		for name, b := range cfg.Backends {
96			if b.Provider == "" {
97				b.Provider = "openai"
98			}
99			cfg.Backends[name] = b
100		}
101	}
102	
103	func validate(cfg *Config) error {
104		for name, b := range cfg.Backends {
105			switch {
106			case b.Model != "" && b.URL != "":
107				return &ValidationError{
108					Field:   "backends." + name,
109					Message: "cannot set both model and url",
110				}
111			case b.Model == "" && b.URL == "":
112				return &ValidationError{
113					Field:   "backends." + name,
114					Message: "must set either model or url",
115				}
116			}
117		}
118		return nil
119	}
