package anthropic

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"

	"forge/internal/domain"
	"forge/internal/provider"
)

// Client implements provider.Provider for the Anthropic Messages API.
type Client struct {
	apiKey     string
	baseURL    string
	httpClient *http.Client
	model      string
	useBearer  bool     // use Authorization: Bearer instead of x-api-key
	betaFlags  []string // anthropic-beta header values
}

// New returns a Client. If apiKey is empty, ANTHROPIC_API_KEY env is used.
// model is the default model when Request.Model is empty.
func New(apiKey, model string) *Client {
	if apiKey == "" {
		apiKey = os.Getenv("ANTHROPIC_API_KEY")
	}
	return &Client{
		apiKey:     apiKey,
		baseURL:    "https://api.anthropic.com",
		httpClient: &http.Client{},
		model:      model,
	}
}

// NewBearer returns a Client that authenticates with Authorization: Bearer
// instead of x-api-key. Used for OAuth tokens (e.g. Claude Code credentials).
// Includes the oauth-2025-04-20 beta flag required for OAuth acceptance.
func NewBearer(token, model string) *Client {
	return &Client{
		apiKey:     token,
		baseURL:    "https://api.anthropic.com",
		httpClient: &http.Client{},
		model:      model,
		useBearer:  true,
		betaFlags:  []string{"oauth-2025-04-20"},
	}
}

// Stream implements provider.Provider.
func (c *Client) Capabilities() provider.Capabilities {
	return provider.Capabilities{provider.CapForgeLoop, provider.CapSystemPrompt}
}

func (c *Client) Stream(ctx context.Context, req provider.Request) (<-chan provider.Delta, error) {
	model := req.Model
	if model == "" {
		model = c.model
	}

	body, err := c.buildBody(req, model)
	if err != nil {
		return nil, fmt.Errorf("anthropic: build request: %w", err)
	}

	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/v1/messages", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("anthropic: new request: %w", err)
	}
	httpReq.Header.Set("content-type", "application/json")
	if c.useBearer {
		httpReq.Header.Set("authorization", "Bearer "+c.apiKey)
	} else {
		httpReq.Header.Set("x-api-key", c.apiKey)
	}
	httpReq.Header.Set("anthropic-version", "2023-06-01")
	if len(c.betaFlags) > 0 {
		httpReq.Header.Set("anthropic-beta", strings.Join(c.betaFlags, ","))
	}

	ch := make(chan provider.Delta, 32)
	go c.stream(ctx, httpReq, model, ch)
	return ch, nil
}

// buildBody marshals the provider.Request into the Anthropic API request JSON.
func (c *Client) buildBody(req provider.Request, model string) ([]byte, error) {
	maxTokens := req.MaxTokens
	if maxTokens == 0 {
		maxTokens = 8192
	}

	msgs := make([]apiMessage, len(req.Messages))
	for i, m := range req.Messages {
		msgs[i] = convertMessage(m)
	}

	var tools []apiTool
	if len(req.Tools) > 0 {
		tools = make([]apiTool, len(req.Tools))
		for i, t := range req.Tools {
			tools[i] = apiTool{
				Name:        t.Name,
				Description: t.Description,
				InputSchema: t.InputSchema,
			}
		}
	}

	body := apiRequest{
		Model:     model,
		MaxTokens: maxTokens,
		System:    req.System,
		Messages:  msgs,
		Tools:     tools,
		Stream:    true,
	}
	return json.Marshal(body)
}

// stream runs the HTTP call and SSE processing in a goroutine.
func (c *Client) stream(ctx context.Context, httpReq *http.Request, model string, ch chan<- provider.Delta) {
	defer close(ch)

	resp, err := c.httpClient.Do(httpReq)
	if err != nil {
		ch <- provider.Delta{Type: provider.DeltaTypeError, Err: fmt.Errorf("anthropic: %w", err)}
		ch <- provider.Delta{Type: provider.DeltaTypeDone}
		return
	}
	defer resp.Body.Close()

	if resp.StatusCode/100 != 2 {
		var buf bytes.Buffer
		_, _ = buf.ReadFrom(resp.Body)
		ch <- provider.Delta{
			Type: provider.DeltaTypeError,
			Err:  fmt.Errorf("anthropic: %s: %s", resp.Status, strings.TrimSpace(buf.String())),
		}
		ch <- provider.Delta{Type: provider.DeltaTypeDone}
		return
	}

	sseEvents := make(chan sseEvent, 64)
	go parseSSE(resp.Body, sseEvents)

	type blockState struct {
		kind  string // "text" | "tool_use"
		id    string
		name  string
		input strings.Builder
	}

	blocks := map[int]*blockState{}
	var inputTokens, outputTokens int64
	var usageSent bool

	emitUsage := func() {
		if !usageSent {
			ch <- provider.Delta{
				Type: provider.DeltaTypeUsage,
				Usage: &domain.Usage{
					InputTokens:  inputTokens,
					OutputTokens: outputTokens,
					CostUSD:      computeCost(model, inputTokens, outputTokens),
				},
			}
			usageSent = true
		}
	}

	for {
		select {
		case <-ctx.Done():
			ch <- provider.Delta{Type: provider.DeltaTypeError, Err: ctx.Err()}
			ch <- provider.Delta{Type: provider.DeltaTypeDone}
			return

		case ev, ok := <-sseEvents:
			if !ok {
				// SSE channel closed without message_stop.
				emitUsage()
				ch <- provider.Delta{Type: provider.DeltaTypeDone}
				return
			}

			switch ev.Type {
			case "message_start":
				var ms struct {
					Message struct {
						Usage struct {
							InputTokens int64 `json:"input_tokens"`
						} `json:"usage"`
					} `json:"message"`
				}
				if json.Unmarshal([]byte(ev.Data), &ms) == nil {
					inputTokens = ms.Message.Usage.InputTokens
				}

			case "content_block_start":
				var cbs struct {
					Index        int `json:"index"`
					ContentBlock struct {
						Type string `json:"type"`
						ID   string `json:"id"`
						Name string `json:"name"`
					} `json:"content_block"`
				}
				if json.Unmarshal([]byte(ev.Data), &cbs) == nil {
					bs := &blockState{kind: cbs.ContentBlock.Type}
					blocks[cbs.Index] = bs
					if cbs.ContentBlock.Type == "tool_use" {
						bs.id = cbs.ContentBlock.ID
						bs.name = cbs.ContentBlock.Name
						ch <- provider.Delta{
							Type: provider.DeltaTypeToolUseStart,
							ID:   bs.id,
							Name: bs.name,
						}
					}
				}

			case "content_block_delta":
				var cbd struct {
					Index int `json:"index"`
					Delta struct {
						Type        string `json:"type"`
						Text        string `json:"text"`
						PartialJSON string `json:"partial_json"`
					} `json:"delta"`
				}
				if json.Unmarshal([]byte(ev.Data), &cbd) == nil {
					bs := blocks[cbd.Index]
					switch cbd.Delta.Type {
					case "text_delta":
						ch <- provider.Delta{
							Type: provider.DeltaTypeText,
							Text: cbd.Delta.Text,
						}
					case "input_json_delta":
						if bs != nil {
							bs.input.WriteString(cbd.Delta.PartialJSON)
							ch <- provider.Delta{
								Type:  provider.DeltaTypeToolUseDelta,
								ID:    bs.id,
								Input: cbd.Delta.PartialJSON,
							}
						}
					}
				}

			case "content_block_stop":
				var cbs struct {
					Index int `json:"index"`
				}
				if json.Unmarshal([]byte(ev.Data), &cbs) == nil {
					if bs := blocks[cbs.Index]; bs != nil && bs.kind == "tool_use" {
						ch <- provider.Delta{
							Type:  provider.DeltaTypeToolUseEnd,
							ID:    bs.id,
							Input: bs.input.String(),
						}
					}
				}

			case "message_delta":
				var md struct {
					Usage struct {
						OutputTokens int64 `json:"output_tokens"`
					} `json:"usage"`
				}
				if json.Unmarshal([]byte(ev.Data), &md) == nil {
					outputTokens = md.Usage.OutputTokens
					emitUsage()
				}

			case "message_stop":
				emitUsage()
				ch <- provider.Delta{Type: provider.DeltaTypeDone}
				return
			}
		}
	}
}

// convertMessage converts a provider.Message to the Anthropic API message format.
func convertMessage(m provider.Message) apiMessage {
	blocks := make([]apiBlock, len(m.Content))
	for i, b := range m.Content {
		blocks[i] = convertBlock(b)
	}
	return apiMessage{Role: string(m.Role), Content: blocks}
}

// convertBlock converts a provider.ContentBlock to the Anthropic API block format.
func convertBlock(b provider.ContentBlock) apiBlock {
	switch b.Type {
	case "text":
		return apiBlock{Type: "text", Text: b.Text}
	case "tool_use":
		input := b.Input
		if len(input) == 0 {
			input = json.RawMessage(`{}`)
		}
		return apiBlock{Type: "tool_use", ID: b.ID, Name: b.Name, Input: input}
	case "tool_result":
		return apiBlock{Type: "tool_result", ToolUseID: b.ID, Content: b.Content, IsError: b.IsError}
	default:
		return apiBlock{Type: b.Type, Text: b.Text}
	}
}

// --- Anthropic API wire types ---

type apiRequest struct {
	Model     string       `json:"model"`
	MaxTokens int          `json:"max_tokens"`
	System    string       `json:"system,omitempty"`
	Messages  []apiMessage `json:"messages"`
	Tools     []apiTool    `json:"tools,omitempty"`
	Stream    bool         `json:"stream"`
}

type apiMessage struct {
	Role    string     `json:"role"`
	Content []apiBlock `json:"content"`
}

type apiBlock struct {
	Type string `json:"type"`
	// text
	Text string `json:"text,omitempty"`
	// tool_use
	ID    string          `json:"id,omitempty"`
	Name  string          `json:"name,omitempty"`
	Input json.RawMessage `json:"input,omitempty"`
	// tool_result
	ToolUseID string `json:"tool_use_id,omitempty"`
	Content   string `json:"content,omitempty"`
	IsError   bool   `json:"is_error,omitempty"`
}

type apiTool struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"input_schema"`
}

