package anthropic

import (
	"bufio"
	"io"
	"strings"
)

// sseEvent holds one parsed SSE event.
type sseEvent struct {
	Type string
	Data string
}

// parseSSE reads SSE events from r until EOF or error.
// Sends each complete event (with non-empty Data) to events.
// Closes events when done.
func parseSSE(r io.Reader, events chan<- sseEvent) {
	defer close(events)

	scanner := bufio.NewScanner(r)
	var curType, curData string

	for scanner.Scan() {
		line := scanner.Text()
		switch {
		case strings.HasPrefix(line, "event:"):
			curType = strings.TrimSpace(line[6:])
		case strings.HasPrefix(line, "data:"):
			data := strings.TrimSpace(line[5:])
			if data == "[DONE]" {
				continue
			}
			curData = data
		case line == "":
			if curData != "" {
				events <- sseEvent{Type: curType, Data: curData}
			}
			curType = ""
			curData = ""
		}
	}

	// Send any trailing event not followed by a blank line.
	if curData != "" {
		events <- sseEvent{Type: curType, Data: curData}
	}
}

