						ch <- provider.Delta{
							Type:  provider.DeltaTypeToolUseEnd,
							ID:    state.id,
							Input: state.args.String(),
						}
					}
				}
			}
		}
	}
}

// buildMessages converts a provider.Request to the OpenAI wire message format.
// One provider.Message may expand into multiple OpenAI messages.
func buildMessages(req provider.Request) []apiMessage {
	var msgs []apiMessage

	if req.System != "" {
		msgs = append(msgs, apiMessage{Role: "system", Content: req.System})
	}

	for _, m := range req.Messages {
		switch m.Role {
		case domain.RoleUser:
			// tool_result blocks become role="tool" messages first.
			for _, b := range m.Content {
				if b.Type == "tool_result" {
					msgs = append(msgs, apiMessage{
						Role:       "tool",
						Content:    b.Content,
						ToolCallID: b.ID,
					})
				}
			}
			// Text blocks concatenated into a user message.
			var sb strings.Builder
			for _, b := range m.Content {
				if b.Type == "text" {
					sb.WriteString(b.Text)
				}
			}
			if sb.Len() > 0 {
				msgs = append(msgs, apiMessage{Role: "user", Content: sb.String()})
			}

		case domain.RoleAssistant:
			var sb strings.Builder
			var toolCalls []apiToolCall
			for _, b := range m.Content {
				switch b.Type {
				case "text":
					sb.WriteString(b.Text)
				case "tool_use":
					toolCalls = append(toolCalls, apiToolCall{
						ID:   b.ID,
						Type: "function",
						Function: apiFunction{
							Name:      b.Name,
							Arguments: orEmptyObj(b.Input),
						},
					})
				}
			}
			msg := apiMessage{Role: "assistant", ToolCalls: toolCalls}
			if sb.Len() > 0 {
				msg.Content = sb.String()
			}
			// nil Content marshals as JSON null — correct for tool-only assistant messages.
			msgs = append(msgs, msg)
		}
	}

	return msgs
}

// --- OpenAI API wire types ---

type apiRequest struct {
	Model         string            `json:"model"`
	Messages      []apiMessage      `json:"messages"`
	Tools         []apiTool         `json:"tools,omitempty"`
	Stream        bool              `json:"stream"`
	StreamOptions *apiStreamOptions `json:"stream_options,omitempty"`
	MaxTokens     int               `json:"max_tokens,omitempty"`
}

type apiStreamOptions struct {
	IncludeUsage bool `json:"include_usage"`
}

type apiMessage struct {
	Role       string        `json:"role"`
	Content    any           `json:"content"`
	ToolCalls  []apiToolCall `json:"tool_calls,omitempty"`
	ToolCallID string        `json:"tool_call_id,omitempty"`
}

type apiToolCall struct {
	ID       string      `json:"id"`
	Type     string      `json:"type"`
	Function apiFunction `json:"function"`
}

type apiFunction struct {
	Name      string `json:"name"`
	Arguments string `json:"arguments"`
}

type apiTool struct {
	Type     string     `json:"type"`
	Function apiFuncDef `json:"function"`
}

type apiFuncDef struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	Parameters  json.RawMessage `json:"parameters"`
}

// --- SSE chunk wire types ---

type chunk struct {
	Choices []chunkChoice `json:"choices"`
	Usage   *chunkUsage   `json:"usage"`
}

type chunkChoice struct {
	Delta        chunkDelta `json:"delta"`
	FinishReason *string    `json:"finish_reason"`
}

type chunkDelta struct {
	Content   *string    `json:"content"`
	ToolCalls []tcChunk  `json:"tool_calls"`
}

type tcChunk struct {
	Index    int         `json:"index"`
	ID       string      `json:"id"`
	Function tcFuncChunk `json:"function"`
}

type tcFuncChunk struct {
	Name      string `json:"name"`
	Arguments string `json:"arguments"`
}

type chunkUsage struct {
	PromptTokens     int64 `json:"prompt_tokens"`
	CompletionTokens int64 `json:"completion_tokens"`
}

// orEmptyObj returns the JSON string of input, defaulting to "{}" if empty.
func orEmptyObj(input json.RawMessage) string {
	if len(input) == 0 {
		return "{}"
	}
	return string(input)
}

