201				}
202				antMsgs = append(antMsgs, antMsg{Role: "assistant", Content: blocks})
203	
204			case "tool":
205				pendingToolResults = append(pendingToolResults, antBlock{
206					Type:      "tool_result",
207					ToolUseID: m.ToolCallID,
208					Content:   extractTextContent(m.Content),
209				})
