261					ID:   block.ID,
262					Type: "function",
263					Function: oaiFunction{
264						Name:      block.Name,
265						Arguments: args,
266					},
267				})
268			}
269		}
270	
271		var content *string
272		if s := textBuf.String(); s != "" {
273			content = &s
274		}
275	
276		return json.Marshal(oaiResponse{
277			ID:      "chatcmpl-" + resp.ID,
278			Object:  "chat.completion",
279			Created: time.Now().Unix(),
280			Model:   model,
281			Choices: []oaiChoice{{
282				Index: 0,
283				Message: oaiMsgOut{
284					Role:      "assistant",
285					Content:   content,
286					ToolCalls: toolCalls,
287				},
288				FinishReason: mapStopReason(resp.StopReason),
289			}},
290			Usage: oaiUsage{
291				PromptTokens:     resp.Usage.InputTokens,
292				CompletionTokens: resp.Usage.OutputTokens,
293				TotalTokens:      resp.Usage.InputTokens + resp.Usage.OutputTokens,
294			},
295		})
296	}
297	
298	// mapStopReason converts Anthropic stop_reason to OpenAI finish_reason.
299	func mapStopReason(reason string) string {
300		switch reason {
301		case "end_turn":
302			return "stop"
303		case "tool_use":
304			return "tool_calls"
305		case "max_tokens":
306			return "length"
307		default:
308			return "stop"
309		}
310	}
311	
312	// extractTextContent parses an OpenAI content field, which can be a JSON
313	// string or an array of content parts, and returns the plain text.
314	func extractTextContent(raw json.RawMessage) string {
315		if len(raw) == 0 || string(raw) == "null" {
316			return ""
317		}
318		var s string
319		if json.Unmarshal(raw, &s) == nil {
320			return s
321		}
322		var parts []struct {
323			Type string `json:"type"`
324			Text string `json:"text"`
325		}
326		if json.Unmarshal(raw, &parts) == nil {
327			var b strings.Builder
328			for _, p := range parts {
329				if p.Type == "text" {
330					b.WriteString(p.Text)
331				}
332			}
333			return b.String()
334		}
335		return ""
336	}
