1	package anthropic
2	
3	import (
4		"encoding/json"
5		"net/http/httptest"
6		"strings"
7		"testing"
8	)
9	
10	const testModel = "claude-3-5-sonnet-20241022"
11	
12	// --- TranslateRequest tests ---
13	
14	func TestTranslateRequest_Basic(t *testing.T) {
15		req := `{"model":"gpt-4","messages":[{"role":"user","content":"Hello"}]}`
16		got, err := TranslateRequest([]byte(req), testModel)
17		if err != nil {
18			t.Fatalf("unexpected error: %v", err)
19		}
20	
21		var ant antRequest
22		if err := json.Unmarshal(got, &ant); err != nil {
23			t.Fatalf("unmarshal: %v", err)
24		}
25	
26		if ant.Model != testModel {
27			t.Errorf("model = %q, want %q", ant.Model, testModel)
28		}
29		if ant.MaxTokens != 8192 {
30			t.Errorf("max_tokens = %d, want 8192 (default)", ant.MaxTokens)
31		}
32		if len(ant.Messages) != 1 {
33			t.Fatalf("messages len = %d, want 1", len(ant.Messages))
34		}
35		if ant.Messages[0].Role != "user" {
36			t.Errorf("role = %q, want user", ant.Messages[0].Role)
37		}
38		if len(ant.Messages[0].Content) != 1 || ant.Messages[0].Content[0].Text != "Hello" {
39			t.Errorf("content = %+v, want text block with Hello", ant.Messages[0].Content)
40		}
41	}
42	
43	func TestTranslateRequest_MaxTokensPreserved(t *testing.T) {
44		req := `{"model":"gpt-4","messages":[{"role":"user","content":"hi"}],"max_tokens":500}`
45		got, err := TranslateRequest([]byte(req), testModel)
46		if err != nil {
47			t.Fatalf("unexpected error: %v", err)
48		}
49		var ant antRequest
50		json.Unmarshal(got, &ant) //nolint:errcheck
51		if ant.MaxTokens != 500 {
52			t.Errorf("max_tokens = %d, want 500", ant.MaxTokens)
53		}
54	}
55	
56	func TestTranslateRequest_SystemMessage(t *testing.T) {
57		req := `{"model":"gpt-4","messages":[{"role":"system","content":"Be helpful"},{"role":"user","content":"Hi"}]}`
58		got, err := TranslateRequest([]byte(req), testModel)
59		if err != nil {
60			t.Fatalf("unexpected error: %v", err)
61		}
62	
63		var ant antRequest
64		json.Unmarshal(got, &ant) //nolint:errcheck
65	
66		if ant.System != "Be helpful" {
67			t.Errorf("system = %q, want %q", ant.System, "Be helpful")
68		}
69		// System message must not appear in messages array.
70		for _, m := range ant.Messages {
71			if m.Role == "system" {
72				t.Error("system role found in messages array")
73			}
74		}
75		if len(ant.Messages) != 1 {
76			t.Errorf("messages len = %d, want 1", len(ant.Messages))
77		}
78	}
79	
80	func TestTranslateRequest_ToolCalls(t *testing.T) {
81		req := `{
82			"model": "gpt-4",
83			"messages": [
84				{"role": "user", "content": "What's the weather?"},
85				{"role": "assistant", "content": null, "tool_calls": [
86					{"id": "call_abc123", "type": "function", "function": {"name": "get_weather", "arguments": "{\"location\":\"NYC\"}"}}
87				]},
88				{"role": "tool", "tool_call_id": "call_abc123", "content": "Sunny, 75F"}
89			]
90		}`
91		got, err := TranslateRequest([]byte(req), testModel)
92		if err != nil {
93			t.Fatalf("unexpected error: %v", err)
94		}
95	
96		var ant antRequest
97		json.Unmarshal(got, &ant) //nolint:errcheck
98	
99		// Expect: user, assistant, user(tool_result)
100		if len(ant.Messages) != 3 {
101			t.Fatalf("messages len = %d, want 3", len(ant.Messages))
102		}
103	
104		// assistant message should have tool_use block
105		asst := ant.Messages[1]
106		if asst.Role != "assistant" {
107			t.Errorf("msg[1].role = %q, want assistant", asst.Role)
108		}
109		if len(asst.Content) != 1 || asst.Content[0].Type != "tool_use" {
110			t.Fatalf("msg[1].content = %+v, want one tool_use block", asst.Content)
111		}
112		if asst.Content[0].ID != "call_abc123" {
113			t.Errorf("tool_use.id = %q, want call_abc123", asst.Content[0].ID)
114		}
115		if asst.Content[0].Name != "get_weather" {
116			t.Errorf("tool_use.name = %q, want get_weather", asst.Content[0].Name)
117		}
118	
119		// Tool result should be folded into a user message
120		toolResultMsg := ant.Messages[2]
121		if toolResultMsg.Role != "user" {
122			t.Errorf("msg[2].role = %q, want user", toolResultMsg.Role)
123		}
124		if len(toolResultMsg.Content) != 1 || toolResultMsg.Content[0].Type != "tool_result" {
125			t.Fatalf("msg[2].content = %+v, want one tool_result block", toolResultMsg.Content)
126		}
127		if toolResultMsg.Content[0].ToolUseID != "call_abc123" {
128			t.Errorf("tool_result.tool_use_id = %q, want call_abc123", toolResultMsg.Content[0].ToolUseID)
129		}
130		if toolResultMsg.Content[0].Content != "Sunny, 75F" {
131			t.Errorf("tool_result.content = %q, want Sunny, 75F", toolResultMsg.Content[0].Content)
132		}
133	}
134	
135	func TestTranslateRequest_ToolCallIDPreserved(t *testing.T) {
136		req := `{
137			"model": "gpt-4",
138			"messages": [
139				{"role": "user", "content": "Run it"},
140				{"role": "assistant", "content": null, "tool_calls": [
141					{"id": "call_XYZ789", "type": "function", "function": {"name": "run", "arguments": "{}"}}
142				]},
143				{"role": "tool", "tool_call_id": "call_XYZ789", "content": "done"}
