434				continue
435			}
436			tc := c.Choices[0].Delta.ToolCalls[0]
437			if tc.ID == "toolu_xyz" && tc.Function.Name == "get_weather" {
438				foundHeader = true
439				if tc.Function.Arguments != nil && *tc.Function.Arguments == "" {
440					// initial args chunk is empty string
441				}
442			}
