463			`data: {"type":"message_start","message":{"id":"msg_3","type":"message","role":"assistant","content":[],"model":"claude","stop_reason":null,"usage":{"input_tokens":5,"output_tokens":0}}}` + "\n\n" +
464			"event: ping\n" +
465			`data: {"type":"ping"}` + "\n\n" +
466			"event: message_stop\n" +
467			`data: {"type":"message_stop"}` + "\n\n"
468	
469		w := httptest.NewRecorder()
470		TranslateStream(strings.NewReader(stream), w, "my-model")
471	
472		body := w.Body.String()
473		if !strings.Contains(body, "data: [DONE]") {
474			t.Error("expected [DONE] in output")
475		}
476		// ping should not appear as a data chunk
477		chunks := parseOAISSEChunks(t, body)
478		// Should have: message_start chunk + message_stop [DONE] (no ping chunk)
479		for _, c := range chunks {
480			raw, _ := json.Marshal(c)
481			if strings.Contains(string(raw), "ping") {
482				t.Error("ping event leaked into output")
483			}
484		}
485	}
486	
487	// --- helpers ---
488	
489	// parseOAISSE returns all chunks (excluding [DONE]) from an OpenAI SSE body.
490	func parseOAISSE(t *testing.T, body string) []oaiChunk {
491		t.Helper()
492		return parseOAISSEChunks(t, body)
493	}
494	
495	func parseOAISSEChunks(t *testing.T, body string) []oaiChunk {
496		t.Helper()
497		var chunks []oaiChunk
498		for _, line := range strings.Split(body, "\n") {
499			line = strings.TrimSpace(line)
500			if !strings.HasPrefix(line, "data: ") {
501				continue
502			}
503			data := line[6:]
504			if data == "[DONE]" {
505				continue
506			}
507			var c oaiChunk
508			if err := json.Unmarshal([]byte(data), &c); err != nil {
509				t.Fatalf("parse chunk %q: %v", data, err)
510			}
511			chunks = append(chunks, c)
512		}
513		return chunks
514	}
